/**
 * Universal Data Tree Adapter.
 *
 * Converts arbitrary JavaScript structures (objects, arrays, primitives)
 * into a typed AST consumable by DataTree.vue and PhpSerializedTreeNode.vue.
 * Pass-through for AST nodes already generated by parsePhpSerialized.
 */

import { PHP_AST_BRAND } from './php-serializer/parser.js';

/**
 * Maximum nesting depth explored when converting JS structures.
 */
export const MAX_TREE_DEPTH = 32;

/**
 * Checks whether an item is already a parsed PHP AST node.
 *
 * Only nodes produced by parsePhpSerialized() carry the (non-enumerable) brand, so
 * arbitrary JSON payloads such as `{ "type": "text", "value": "foo" }` are never
 * mistaken for AST nodes.
 *
 * @param {any} node
 * @returns {boolean}
 */
export function isPhpAstNode(node) {
  return Boolean(node && typeof node === 'object' && node[PHP_AST_BRAND] === true);
}

/**
 * Resolves a display class name from the prototype chain, ignoring any own
 * `constructor` property supplied by the payload itself.
 *
 * @param {object} data
 * @returns {string}
 */
function resolveClassName(data) {
  const proto = Object.getPrototypeOf(data);
  const ctor = proto && Object.prototype.hasOwnProperty.call(proto, 'constructor') ? proto.constructor : null;
  const name = typeof ctor === 'function' ? ctor.name : '';
  return name && name !== 'Object' ? name : 'Object';
}

/**
 * Recursively converts any JS value or JSON structure to a Tree AST.
 *
 * @param {any} data - JS object, array, primitive or existing AST.
 * @param {WeakSet} [ancestors] - Objects on the current path (cycle detection).
 * @param {number} [depth] - Current nesting depth.
 * @returns {object} - AST Node.
 */
export function convertToTreeAst(data, ancestors = new WeakSet(), depth = 0) {
  if (data === null) {
    return { type: 'null', raw: 'null' };
  }

  if (data === undefined) {
    return { type: 'null', raw: 'undefined' };
  }

  if (typeof data === 'boolean') {
    return { type: 'boolean', value: data };
  }

  if (typeof data === 'number') {
    return Number.isInteger(data)
      ? { type: 'integer', value: data }
      : { type: 'double', value: data };
  }

  if (typeof data === 'string') {
    return { type: 'string', value: data };
  }

  // Already an AST node (from PHP serializer parser)
  if (isPhpAstNode(data)) {
    return data;
  }

  if (typeof data === 'object') {
    if (ancestors.has(data)) {
      return { type: 'circular', value: '[Circular]' };
    }
    if (depth > MAX_TREE_DEPTH) {
      return { type: 'max-depth', value: '[Max depth reached]' };
    }

    // Only ancestors are tracked, so shared (non-cyclic) references such as
    // `{ a: x, b: x }` are rendered twice instead of being flagged as circular.
    ancestors.add(data);
    try {
      if (Array.isArray(data)) {
        return {
          type: 'array',
          count: data.length,
          entries: data.map((val, idx) => ({
            key: { type: 'integer', value: idx },
            value: convertToTreeAst(val, ancestors, depth + 1),
          })),
        };
      }

      const keys = Object.keys(data);

      return {
        type: 'object',
        className: resolveClassName(data),
        propertyCount: keys.length,
        properties: keys.map((key) => ({
          name: key,
          visibility: null,
          value: convertToTreeAst(data[key], ancestors, depth + 1),
        })),
      };
    } finally {
      ancestors.delete(data);
    }
  }

  return { type: 'string', value: String(data) };
}
